def is_sequence(nums, patterns):
    """
    Checks whether the given list of numbers follows the sequence given in the patterns array.

    Args:
    nums (list): The list of numbers to check.
    patterns (list): A list of sequences to check against.

    Returns:
    bool: True if the list of numbers follows one of the sequences, False otherwise.
    """
    for pattern in patterns:
        if len(nums) != len(pattern):
            continue
        is_match = True
        for i in range(len(nums)):
            if nums[i] != pattern[i]:
                is_match = False
                break
        if is_match:
            return True
    return False

